    out = [row[:] for row in grid]
    labels = [[-1] * w for _ in range(h)]
    component_markers = []
    all_markers = []

    # Find 4-connected nonzero components and any colored markers in them.
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or labels[r][c] != -1:
                continue
            cid = len(component_markers)
            stack = [(r, c)]
            labels[r][c] = cid
            markers = []
            while stack:
                y, x = stack.pop()
                if grid[y][x] not in (0, 1):
                    marker = (y, x, grid[y][x])
                    markers.append(marker)
                    all_markers.append(marker)
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and
                            grid[ny][nx] != 0 and labels[ny][nx] == -1):
                        labels[ny][nx] = cid
                        stack.append((ny, nx))
            component_markers.append(markers)

    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if grid[r][c] != 1:
                continue
            # Color only cells whose entire 3x3 neighborhood is nonzero.
            if not all(grid[y][x] != 0
                       for y in range(r - 1, r + 2)
                       for x in range(c - 1, c + 2)):
                continue

            markers = component_markers[labels[r][c]] or all_markers
            if markers:
                _, _, color = min(
                    markers,
                    key=lambda m: abs(r - m[0]) + abs(c - m[1])
                )
                out[r][c] = color

